import os
import numpy as np

# =============================================================================
# DIRECTORY AND FILE PATHS
# =============================================================================
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"
WORKING_DIR = "./working/idea_24/"
SUBMISSION_DIR = "./submission"

# Ensure output directories exist
os.makedirs(WORKING_DIR, exist_ok=True)
os.makedirs(SUBMISSION_DIR, exist_ok=True)

# Metadata File Paths (Generated by previous steps)
TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.csv")
VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.csv")
TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.csv")

# Final Submission File Path
SUBMISSION_FILE_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

# =============================================================================
# GLOBAL CONFIGURATION
# =============================================================================
# Random Seed for Reproducibility across numpy, sklearn, etc.
RANDOM_SEED = 42

# Float Precision for High-Precision Arithmetic
# Critical for overcoming the float32 numerical ceiling identified in analysis
FLOAT_PRECISION = np.float64

# =============================================================================
# DATA CONFIGURATION
# =============================================================================
ID_COL = "id"
TARGET_COL = "species"

# Feature Definitions
# Programmatically generate the 64-attribute vector names for each feature set
MARGIN_COLS = [f"margin_{i}" for i in range(1, 65)]
SHAPE_COLS = [f"shape_{i}" for i in range(1, 65)]
TEXTURE_COLS = [f"texture_{i}" for i in range(1, 65)]

# Combined Feature List (Deterministic Order)
# This ensures that the feature vector is always constructed in the same order
FEATURE_COLS = MARGIN_COLS + SHAPE_COLS + TEXTURE_COLS

# =============================================================================
# MODEL HYPERPARAMETERS
# =============================================================================
# Synthetic Data Generation (Teacher: OAS-LDA)
# Number of synthetic samples to generate per class to densely map the manifold
# 10,000 samples * 99 classes = ~1M total training samples for the student
N_SYNTHETIC = 10000

# Student Model (Discriminative: Logistic Regression)
# Inverse regularization strength.
# We use a very high C (1e6) to minimize regularization, effectively trusting
# the "clean" synthetic manifold generated by the Teacher.
C_STUDENT = 1e6
SOLVER = "lbfgs"
MAX_ITER = 1000
TOL = 1e-6

# Preprocessing Configuration
# Apply Yeo-Johnson Power Transformation to normalize feature distributions
APPLY_POWER_TRANSFORM = True
# Apply Standard Scaling (z-score)
APPLY_SCALING = True

# =============================================================================
# POST-PROCESSING
# =============================================================================
# Probability Clipping to avoid Log Loss extremes as per metric definition
# max(min(p, 1-10^-15), 10^-15)
PROB_CLIP_MIN = 1e-15
PROB_CLIP_MAX = 1.0 - 1e-15

# =============================================================================
# DEBUGGING AND DEVELOPMENT
# =============================================================================
# Flags to control runtime during development
DEBUG_MODE = False
DEBUG_SAMPLE_SIZE = 100  # Number of samples to use if DEBUG_MODE is True
